import React, { useState } from 'react';
import { Mail, Lock, User, Phone, ArrowRight, Shield, CheckCircle } from 'lucide-react';

export default function Signin({ onLoginSuccess }) {
  // Toggle between 'login' and 'signup'
  const [mode, setMode] = useState('login');

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    emailOrPhone: '',
    phone: '',
    password: '',
    confirmPassword: '',
    role: 'Passenger' // Default role
  });

  // UI Feedback States
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // Handle Input Changes
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
    setSuccess('');
  };

  // Clear Form Data on Switch
  const switchTab = (newMode) => {
    setMode(newMode);
    setError('');
    setSuccess('');
    setFormData({
      name: '',
      emailOrPhone: '',
      phone: '',
      password: '',
      confirmPassword: '',
      role: 'Passenger'
    });
  };

  // Form Submission
  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    // --- SIGN UP LOGIC ---
    if (mode === 'signup') {
      if (!formData.name || !formData.emailOrPhone || !formData.password) {
        setError('Please fill in all required fields.');
        return;
      }

      if (formData.password !== formData.confirmPassword) {
        setError('Passwords do not match!');
        return;
      }

      if (formData.password.length < 6) {
        setError('Password must be at least 6 characters long.');
        return;
      }

      // Fetch existing registered users from LocalStorage
      const existingUsers = JSON.parse(localStorage.getItem('app_users') || '[]');

      // Check if user already exists
      const userExists = existingUsers.some(
        (u) => u.email === formData.emailOrPhone || u.phone === formData.phone
      );

      if (userExists) {
        setError('An account with this email or phone number already exists.');
        return;
      }

      // Create new real user record with initial activity log
      const newUser = {
        id: 'USR-' + Math.floor(1000 + Math.random() * 9000),
        name: formData.name,
        email: formData.emailOrPhone,
        phone: formData.phone || 'N/A',
        password: formData.password, // Saved for local validation
        role: formData.role,
        joined: new Date().toISOString().split('T')[0],
        status: 'Active',
        history: [
          {
            id: 'LOG-001',
            type: 'Account Created',
            date: new Date().toISOString().split('T')[0],
            details: `Registered as ${formData.role} via standard sign-up.`
          }
        ]
      };

      // Save user persistently into LocalStorage
      existingUsers.push(newUser);
      localStorage.setItem('app_users', JSON.stringify(existingUsers));

      setSuccess('Account created successfully! Switching to sign in...');
      
      // Auto-switch to login after short delay
      setTimeout(() => {
        switchTab('login');
      }, 1500);

      return;
    }

    // --- SIGN IN LOGIC ---
    if (mode === 'login') {
      if (!formData.emailOrPhone || !formData.password) {
        setError('Please enter your email/phone and password.');
        return;
      }

      // Check for Super Admin override credentials
      if (formData.emailOrPhone === 'admin@onlinebus.bd' && formData.password === 'admin123') {
        const adminUser = {
          name: 'Super Admin',
          emailOrPhone: 'admin@onlinebus.bd',
          role: 'admin'
        };
        if (onLoginSuccess) onLoginSuccess(adminUser);
        return;
      }

      const existingUsers = JSON.parse(localStorage.getItem('app_users') || '[]');

      // Find matching real user
      const foundUser = existingUsers.find(
        (u) => (u.email === formData.emailOrPhone || u.phone === formData.emailOrPhone) && u.password === formData.password
      );

      if (foundUser) {
        // Authenticate found real user
        if (onLoginSuccess) {
          onLoginSuccess({
            id: foundUser.id,
            name: foundUser.name,
            emailOrPhone: foundUser.email,
            phone: foundUser.phone,
            role: foundUser.role
          });
        }
      } else {
        setError('Invalid credentials. Please check your details or sign up.');
      }
    }
  };

  return (
    <div style={styles.wrapper}>
      <div style={styles.card}>
        {/* Header Toggle */}
        <div style={styles.header}>
          <h2 style={styles.title}>{mode === 'login' ? 'Welcome Back' : 'Create Account'}</h2>
          <p style={styles.subtitle}>
            {mode === 'login' 
              ? 'Access your bookings and management dashboard' 
              : 'Sign up to start booking bus tickets immediately'}
          </p>
        </div>

        {/* Tab Selector */}
        <div style={styles.tabContainer}>
          <button 
            type="button" 
            style={{ ...styles.tab, ...(mode === 'login' ? styles.activeTab : {}) }}
            onClick={() => switchTab('login')}
          >
            Sign In
          </button>
          <button 
            type="button" 
            style={{ ...styles.tab, ...(mode === 'signup' ? styles.activeTab : {}) }}
            onClick={() => switchTab('signup')}
          >
            Register
          </button>
        </div>

        {/* Alert Messages */}
        {error && <div style={styles.errorBox}>{error}</div>}
        {success && (
          <div style={styles.successBox}>
            <CheckCircle size={16} /> {success}
          </div>
        )}

        {/* Form Fields */}
        <form onSubmit={handleSubmit} style={styles.form}>
          {mode === 'signup' && (
            <div style={styles.inputGroup}>
              <label style={styles.label}>Full Name</label>
              <div style={styles.inputWrapper}>
                <User size={18} color="#71717a" style={styles.icon} />
                <input
                  type="text"
                  name="name"
                  placeholder="John Doe"
                  value={formData.name}
                  onChange={handleChange}
                  style={styles.input}
                  required
                />
              </div>
            </div>
          )}

          <div style={styles.inputGroup}>
            <label style={styles.label}>Email Address or Phone Number</label>
            <div style={styles.inputWrapper}>
              <Mail size={18} color="#71717a" style={styles.icon} />
              <input
                type="text"
                name="emailOrPhone"
                placeholder="user@example.com or 01700000000"
                value={formData.emailOrPhone}
                onChange={handleChange}
                style={styles.input}
                required
              />
            </div>
          </div>

          {mode === 'signup' && (
            <div style={styles.inputGroup}>
              <label style={styles.label}>Phone Number (Optional)</label>
              <div style={styles.inputWrapper}>
                <Phone size={18} color="#71717a" style={styles.icon} />
                <input
                  type="text"
                  name="phone"
                  placeholder="+880 1700-000000"
                  value={formData.phone}
                  onChange={handleChange}
                  style={styles.input}
                />
              </div>
            </div>
          )}

          {mode === 'signup' && (
            <div style={styles.inputGroup}>
              <label style={styles.label}>Account Role</label>
              <div style={styles.inputWrapper}>
                <Shield size={18} color="#71717a" style={styles.icon} />
                <select
                  name="role"
                  value={formData.role}
                  onChange={handleChange}
                  style={styles.select}
                >
                  <option value="Passenger">Passenger</option>
                  <option value="Operator">Bus Operator</option>
                  <option value="admin">Admin</option>
                </select>
              </div>
            </div>
          )}

          <div style={styles.inputGroup}>
            <label style={styles.label}>Password</label>
            <div style={styles.inputWrapper}>
              <Lock size={18} color="#71717a" style={styles.icon} />
              <input
                type="password"
                name="password"
                placeholder="••••••••"
                value={formData.password}
                onChange={handleChange}
                style={styles.input}
                required
              />
            </div>
          </div>

          {mode === 'signup' && (
            <div style={styles.inputGroup}>
              <label style={styles.label}>Confirm Password</label>
              <div style={styles.inputWrapper}>
                <Lock size={18} color="#71717a" style={styles.icon} />
                <input
                  type="password"
                  name="confirmPassword"
                  placeholder="••••••••"
                  value={formData.confirmPassword}
                  onChange={handleChange}
                  style={styles.input}
                  required
                />
              </div>
            </div>
          )}

          <button type="submit" style={styles.submitBtn}>
            <span>{mode === 'login' ? 'Sign In' : 'Create Account'}</span>
            <ArrowRight size={18} />
          </button>
        </form>
      </div>
    </div>
  );
}

const styles = {
  wrapper: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: '70vh',
    padding: '20px'
  },
  card: {
    backgroundColor: '#27272a',
    border: '1px solid #3f3f46',
    borderRadius: '16px',
    padding: '32px',
    width: '100%',
    maxWidth: '440px',
    boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.5)'
  },
  header: {
    textAlign: 'center',
    marginBottom: '24px'
  },
  title: {
    margin: 0,
    fontSize: '1.5rem',
    fontWeight: '700',
    color: '#ffffff'
  },
  subtitle: {
    margin: '8px 0 0 0',
    fontSize: '0.875rem',
    color: '#a1a1aa'
  },
  tabContainer: {
    display: 'flex',
    backgroundColor: '#18181b',
    padding: '4px',
    borderRadius: '10px',
    marginBottom: '20px'
  },
  tab: {
    flex: 1,
    padding: '10px',
    border: 'none',
    backgroundColor: 'transparent',
    color: '#a1a1aa',
    fontWeight: '600',
    fontSize: '0.875rem',
    borderRadius: '8px',
    cursor: 'pointer',
    transition: 'all 0.2s'
  },
  activeTab: {
    backgroundColor: '#ea580c',
    color: '#ffffff'
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px'
  },
  inputGroup: {
    display: 'flex',
    flexDirection: 'column',
    gap: '6px'
  },
  label: {
    fontSize: '0.8rem',
    fontWeight: '600',
    color: '#d4d4d8'
  },
  inputWrapper: {
    position: 'relative',
    display: 'flex',
    alignItems: 'center'
  },
  icon: {
    position: 'absolute',
    left: '12px'
  },
  input: {
    width: '100%',
    padding: '10px 12px 10px 40px',
    backgroundColor: '#18181b',
    border: '1px solid #3f3f46',
    borderRadius: '8px',
    color: '#ffffff',
    fontSize: '0.9rem',
    outline: 'none'
  },
  select: {
    width: '100%',
    padding: '10px 12px 10px 40px',
    backgroundColor: '#18181b',
    border: '1px solid #3f3f46',
    borderRadius: '8px',
    color: '#ffffff',
    fontSize: '0.9rem',
    outline: 'none',
    cursor: 'pointer'
  },
  submitBtn: {
    marginTop: '8px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    backgroundColor: '#ea580c',
    color: '#ffffff',
    border: 'none',
    padding: '12px',
    borderRadius: '8px',
    fontWeight: '600',
    fontSize: '0.95rem',
    cursor: 'pointer',
    transition: 'background-color 0.2s'
  },
  errorBox: {
    backgroundColor: '#7f1d1d',
    color: '#fca5a5',
    padding: '10px 14px',
    borderRadius: '8px',
    fontSize: '0.85rem',
    marginBottom: '16px'
  },
  successBox: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    backgroundColor: '#14532d',
    color: '#86efac',
    padding: '10px 14px',
    borderRadius: '8px',
    fontSize: '0.85rem',
    marginBottom: '16px'
  }
};
